/** Thrown by every generated reader and by writer cap checks; never a raw RangeError from a DataView. */
export class WireError extends Error {
  readonly code: number;
  constructor(code: number, message: string) {
    super(message);
    this.name = "WireError";
    this.code = code;
  }
}

